func (p Point) Add(q Point) Point { return Point{p.X + q.X, p.Y + q.Y} }
func endpointToCenterParams(x1, y1, rx, ry, phi float64, largeArc, sweep bool, x2, y2 float64) (float64, float64, float64, float64) {
	if nearlyEqual(x1, x2) && nearlyEqual(y1, y2) {
		return x1, y1, 0.0, 0.0
	}
	sinPhi, cosPhi := math.Sincos(phi)
	x1p := cosPhi*(x1-x2)/2.0 + sinPhi*(y1-y2)/2.0
	y1p := -sinPhi*(x1-x2)/2.0 + cosPhi*(y1-y2)/2.0
	lambda := x1p*x1p/rx/rx + y1p*y1p/ry/ry
	if lambda > 1.0 {
		rx *= math.Sqrt(lambda)
		ry *= math.Sqrt(lambda)
	}
	radicand := (rx*rx*ry*ry - rx*rx*y1p*y1p - ry*ry*x1p*x1p) / (rx*rx*y1p*y1p + ry*ry*x1p*x1p)
	if radicand < 0.0 {
		radicand = 0.0
	}
	coef := math.Sqrt(radicand)
	if largeArc == sweep {
		coef = -coef
	}
	cxp := coef * rx * y1p / ry
	cyp := coef * -ry * x1p / rx
	cx := cosPhi*cxp - sinPhi*cyp + (x1+x2)/2.0
	cy := sinPhi*cxp + cosPhi*cyp + (y1+y2)/2.0
	ux := (x1p - cxp) / rx
	uy := (y1p - cyp) / ry
	vx := -(x1p + cxp) / rx
	vy := -(y1p + cyp) / ry
	theta1 := math.Acos(ux / math.Sqrt(ux*ux+uy*uy))
	if uy < 0.0 {
		theta1 = -theta1
	}
	theta1 = normalizeAngle(theta1)
	cosDelta := (ux*vx + uy*vy) / math.Sqrt((ux*ux+uy*uy)*(vx*vx+vy*vy))
	cosDelta = math.Min(1.0, math.Max(-1.0, cosDelta))
	delta := math.Acos(cosDelta)
	if ux*vy-uy*vx < 0.0 {
		delta = -delta
	}
	if !sweep && delta > 0.0 {
		delta -= 2.0 * math.Pi
	} else if sweep && delta < 0.0 {
		delta += 2.0 * math.Pi
	}
	return cx, cy, theta1, theta1 + delta
}

func (p Point) Interpolate(q Point, t float64) Point {
	return Point{(1-t)*p.X + t*q.X, (1-t)*p.Y + t*q.Y}
}

func QuadraticToCubicBezier(startX, startY, x1, y1, x, y float64) (Point, Point) {
	start := Point{X: startX, Y: startY}
	control := Point{X: x1, Y: y1}
	end := Point{X: x, Y: y}
	ctrl1 := start.Interpolate(control, 2.0/3.0)
	ctrl2 := end.Interpolate(control, 2.0/3.0)
	return ctrl1, ctrl2
}
func (p Point) Mul(f float64) Point { return Point{f * p.X, f * p.Y} }
